{"path":"assets/css/styles.css","content":"/* Core layout and utility styles for split_diagonal layout */
:root{--bg:#ffffff;--muted:#6b7280;--accent:#0f766e;--accent-2:#065f46;--surface:#f7faf9;--maxw:1100px}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0f172a;background:var(--bg);line-height:1.5}
.wrap{max-width:var(--maxw);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;z-index:20;border-bottom:1px solid #eef2f1}
.site-header .wrap{display:flex;align-items:center;gap:1rem}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:0.5rem}
.main-nav a{color:var(--muted);text-decoration:none;padding:.5rem .7rem;border-radius:6px}
.main-nav a:hover{background:#eef7f5;color:var(--accent)}
.cta.small{margin-left:auto;padding:.5rem .8rem;background:var(--accent);color:white;border-radius:6px;text-decoration:none}
.btn{display:inline-block;padding:.6rem 1rem;border-radius:8px;border:1px solid transparent;text-decoration:none;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #e6f0ec;color:var(--accent)}
.split-diagonal .hero{position:relative;padding:6rem 0 4rem;background:linear-gradient(180deg,#fbfffc,transparent)}
.hero-inner{display:grid;grid-template-columns:1fr 420px;gap:2rem;align-items:center}
.hero-copy h1{font-size:clamp(1.6rem,2.8vw,2.4rem);margin:0 0 .6rem}
.lede{color:var(--muted);margin:0 0 1rem}
.hero-ctas{display:flex;gap:.8rem;margin:1rem 0}
.meta{list-style:none;padding:0;margin:1rem 0 0;color:var(--muted);display:flex;gap:1rem}
.hero-pattern{width:420px;height:280px;border-radius:12px;overflow:hidden;box-shadow:0 6px 20px rgba(15,23,42,0.06);display:flex;align-items:center;justify-content:center}
.pattern-embed{width:100%;height:100%}
.diagonal-split{position:absolute;right:0;top:0;bottom:0;width:60%;background:linear-gradient(135deg,#f4faf7,#ffffff);transform-origin:right top;clip-path:polygon(10% 0,100% 0,100% 100%,0 100%)}
/* Gallery */
.gallery{padding:4rem 0}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.card{background:var(--surface);padding:1rem;border-radius:12px;border:1px solid #eef6f4}
.card-art{height:110px;border-radius:8px;margin-bottom:.8rem}
/* What to expect */
.what-to-expect{background:#fcfffd;padding:3rem 0;margin-top:2rem;border-top:1px solid #eef7f5}
.what-to-expect ol{margin:1rem 0 0;padding-left:1.2rem}
.note{color:var(--muted);font-size:.95rem}
/* Objections / FAQ */
.objections{padding:3rem 0}
.faq details{background:#fff;border:1px solid #eef7f5;padding:1rem;border-radius:8px;margin-bottom:.6rem}
.faq summary{font-weight:600;cursor:pointer}
/* CTA */
.final-cta{padding:3.2rem 0;text-align:center}
.final-cta .actions{display:flex;gap:1rem;justify-content:center;margin-top:1rem}
/* Footer */
.site-footer{border-top:1px solid #eef7f5;padding:1.2rem 0;margin-top:3rem;background:#fbfffd}
.site-footer p{margin:0;color:var(--muted)}
.small{font-size:.9rem}
/* Modal */
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(7,10,9,0.45);padding:2rem}
.modal[aria-hidden="false"]{display:flex}
.modal-panel{background:#fff;padding:1.2rem;border-radius:12px;width:min(680px,96%);max-height:90vh;overflow:auto;position:relative}
.modal-close{position:absolute;right:12px;top:12px;background:none;border:0;font-size:1.3rem}
.exercise-options{display:flex;gap:.6rem;margin:1rem 0}
.ex-btn{padding:.6rem .9rem;border-radius:8px;border:1px solid #e6f3ef;background:#fbfffe}
.exercise-area{min-height:120px;border-top:1px dashed #eef6f3;padding-top:1rem}
/* Guided breath circle */
.breath-circle{width:120px;height:120px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#dff6ee,#f7fffdf0);margin:1rem auto;display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent-2)}
/* Reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
.reveal.visible{opacity:1;transform:none}
/* Respect user reduced motion preference */
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* Responsive */
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr}
  .hero-pattern{order:-1;width:100%;height:160px}
  .cards{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Main JS: guided exercise modal + scroll reveal with prefers-reduced-motion
(function(){
  // Utilities
  function qs(sel, ctx){return (ctx||document).querySelector(sel)}
  function qsa(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year injection
  qs('#year').textContent = new Date().getFullYear();

  // Modal handling
  var modal = qs('#exerciseModal');
  var modalTitle = qs('#modalTitle');
  var exerciseArea = qs('#exerciseArea');
  var tryBtn = qs('#tryExercise');
  var closeBtn = qs('#closeModal');

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    // focus first actionable element
    var btn = modal.querySelector('.ex-btn');
    if(btn) btn.focus();
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    tryBtn.focus();
    exerciseArea.innerHTML = '';
    // stop any running animations/timeouts
    clearState();
  }

  tryBtn.addEventListener('click', openModal);
  closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target===modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape' && modal.getAttribute('aria-hidden')==='false'){ closeModal(); } });

  // Guided exercises
  var state = { timers:[] };
  function clearState(){ state.timers.forEach(clearTimeout); state.timers=[]; }

  modal.addEventListener('click', function(e){
    var btn = e.target.closest('.ex-btn');
    if(!btn) return;
    var type = btn.getAttribute('data-type');
    startExercise(type);
  });

  function startExercise(type){
    clearState();
    exerciseArea.innerHTML = '';
    if(type==='breathing') startBreathing();
    else if(type==='journaling') startJournaling();
    else if(type==='intention') startIntention();
  }

  // 1) Guided Breathing
  function startBreathing(){
    modalTitle.textContent = 'Guided Breathing — 2 minutes';
    var wrap = document.createElement('div');
    wrap.innerHTML = '<div class="breath-circle" aria-hidden="true">Breathe</div><p class="center">Follow the circle: inhale for 4s, hold 2s, exhale 6s. Repeat until the cue ends.</p><div class="timer" aria-live="polite">120</div>';
    exerciseArea.appendChild(wrap);
    var timerEl = wrap.querySelector('.timer');
    var circle = wrap.querySelector('.breath-circle');
    var seconds = 120;
    timerEl.textContent = seconds;

    // subtle pulsing animation via JS for reduced-motion compatibility
    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!reduce){
      var phase = 0; // 0 inhale,1 hold,2 exhale
      var cycle = function(){
        phase = (phase+1)%3;
        if(phase===0){ circle.style.transform='scale(1.15)'; circle.style.opacity='1'; }
        if(phase===1){ circle.style.transform='scale(1.05)'; }
        if(phase===2){ circle.style.transform='scale(.85)'; circle.style.opacity='.9'; }
        state.timers.push(setTimeout(cycle, 1200));
      };
      cycle();
    }

    var countdown = function(){
      seconds -= 1;
      timerEl.textContent = seconds;
      if(seconds<=0){ timerEl.textContent='Done'; state.timers.forEach(clearTimeout); return; }
      state.timers.push(setTimeout(countdown,1000));
    };
    state.timers.push(setTimeout(countdown,1000));
  }

  // 2) Journaling prompt with short timer
  function startJournaling(){
    modalTitle.textContent = 'Micro‑Journaling — 3 minutes';
    var wrap = document.createElement('div');
    var prompt = 'Name one win today and one small next step you can take tomorrow.';
    wrap.innerHTML = '<p><em>Prompt:</em> '+prompt+'</p><textarea rows="6" style="width:100%;padding:.6rem;border-radius:6px;border:1px solid #eaeaea" aria-label="Journaling area"></textarea><div style="display:flex;gap:.6rem;margin-top:.6rem;align-items:center"><button class="btn primary start-journal">Start 3‑minute timer</button><div class="journal-timer"></div></div>';
    exerciseArea.appendChild(wrap);
    var start = wrap.querySelector('.start-journal');
    var timerEl = wrap.querySelector('.journal-timer');
    var text = wrap.querySelector('textarea');
    start.addEventListener('click', function(){
      var seconds = 180;
      text.focus();
      timerEl.textContent = formatTime(seconds);
      var tick = function(){
        seconds--; timerEl.textContent = formatTime(seconds);
        if(seconds<=0){ timerEl.textContent = 'Time'; return; }
        state.timers.push(setTimeout(tick,1000));
      };
      state.timers.push(setTimeout(tick,1000));
    });
  }

  function formatTime(s){ var m = Math.floor(s/60); var r = s%60; return m+':'+(r<10?('0'+r):r); }

  // 3) Intention setting
  function startIntention(){
    modalTitle.textContent = 'Set an Intention — 1 minute';
    var wrap = document.createElement('div');
    wrap.innerHTML = '<p>Choose a short intention to carry through your next hour.</p><div style="display:flex;gap:.6rem;flex-wrap:wrap"><button class="int-choice">Finish one small task</button><button class="int-choice">Protect my focus</button><button class="int-choice">Prioritize rest</button><button class="int-choice">Be present in conversations</button></div><div style="margin-top:1rem"><em id="savedInt" style="color:var(--muted)"></em></div>';
    exerciseArea.appendChild(wrap);
    wrap.addEventListener('click', function(e){
      var btn = e.target.closest('.int-choice'); if(!btn) return;
      var text = btn.textContent;
      qs('#savedInt').textContent = 'Saved intention: '+text;
      // small visual confirmation
      btn.style.background='#e8fff5'; btn.style.border='1px solid #c6f1e3';
      // hide modal after a short pause
      state.timers.push(setTimeout(closeModal,1000));
    });
  }

  // Scroll reveal logic (supports prefers-reduced-motion)
  function setupReveal(){
    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var elems = qsa('.reveal');
    if(reduce){ elems.forEach(function(el){ el.classList.add('visible'); }); return; }

    if('IntersectionObserver' in window){
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } });
      },{threshold:0.12});
      elems.forEach(function(el){ io.observe(el); });
    } else {
      // fallback: reveal all
      elems.forEach(function(el){ el.classList.add('visible'); });
    }
  }

  // Initialize
  setupReveal();
})();"} 
